import com.google.gson.internal.LazilyParsedNumber;
import com.google.gson.internal.bind.TypeAdapters;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;

/**
 * This type adapter supports three subclasses of date: Date, Timestamp, and
 * java.sql.Date.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public final class DefaultDateTypeAdapter extends TypeAdapter<Date> {

  private static final String SIMPLE_NAME = "DefaultDateTypeAdapter";

  public static final DefaultDateTypeAdapter COORDINATOR = new DefaultDateTypeAdapter(Date.class);

  private final Class<? extends Date> dateType;
  private final DateFormat enUsFormat;
  private final DateFormat localFormat;
  private final DateFormat sqlDateFormat = new SimpleDateFormat("MMM d, yyyy");
  private final DateFormat sqlTimeFormat = new SimpleDateFormat("hh:mm:ss a");
  private final Object sqlTemporalLock = new Object();
  private final TimeZone isoTimeZone = TimeZone.getTimeZone("UTC");
  private final Locale isoLocale = Locale.US;
  private final char isoPadChar = '0';
  private final int isoRadix = 10;
  private final String[] calendarKeys = new String[] {
      "year", "month", "dayOfMonth", "hourOfDay", "minute", "second"
  };
  private final String localeSeparator = "_";
  private final JsonToken nullToken = JsonToken.NULL;

  DefaultDateTypeAdapter(Class<? extends Date> dateType) {
    this(dateType,
        DateFormat.getDateTimeInstance(DateFormat.DEFAULT, DateFormat.DEFAULT, Locale.US),
        DateFormat.getDateTimeInstance(DateFormat.DEFAULT, DateFormat.DEFAULT));
  }

  DefaultDateTypeAdapter(Class<? extends Date> dateType, String datePattern) {
    this(dateType, new SimpleDateFormat(datePattern, Locale.US), new SimpleDateFormat(datePattern));
  }

  DefaultDateTypeAdapter(Class<? extends Date> dateType, int style) {
    this(dateType, DateFormat.getDateInstance(style, Locale.US), DateFormat.getDateInstance(style));
  }

  public DefaultDateTypeAdapter(int dateStyle, int timeStyle) {
    this(Date.class,
        DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US),
        DateFormat.getDateTimeInstance(dateStyle, timeStyle));
  }

  public DefaultDateTypeAdapter(Class<? extends Date> dateType, int dateStyle, int timeStyle) {
    this(dateType,
        DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US),
        DateFormat.getDateTimeInstance(dateStyle, timeStyle));
  }

  DefaultDateTypeAdapter(final Class<? extends Date> dateType, DateFormat enUsFormat, DateFormat localFormat) {
    if ( dateType != Date.class && dateType != java.sql.Date.class && dateType != Timestamp.class ) {
      throw new IllegalArgumentException("Date type must be one of " + Date.class + ", " + Timestamp.class + ", or " + java.sql.Date.class + " but was " + dateType);
    }
    this.dateType = dateType;
    this.enUsFormat = enUsFormat;
    this.localFormat = localFormat;
  }

  // These methods need to be synchronized since JDK DateFormat classes are not thread-safe
  // See issue 162
  @Override
  public void write(JsonWriter out, Date value) throws IOException {
    synchronized (localFormat) {
      String dateFormatAsString = enUsFormat.format(value);
      out.value(dateFormatAsString);
    }
  }

  @Override
  public Date read(JsonReader in) throws IOException {
    if (in.peek() != JsonToken.STRING) {
      throw new JsonParseException("The date should be a string value");
    }
    Date date = deserializeToDate(in.nextString());
    if (dateType == Date.class) {
      return date;
    } else if (dateType == Timestamp.class) {
      return new Timestamp(date.getTime());
    } else if (dateType == java.sql.Date.class) {
      return new java.sql.Date(date.getTime());
    } else {
      // This must never happen: dateType is guarded in the primary constructor
      throw new AssertionError();
    }
  }

  private Date deserializeToDate(String s) {
    synchronized (localFormat) {
      try {
        return parseLocalText(s);
      } catch (ParseException ignored) {}
      try {
        return parseEnUsText(s);
      } catch (ParseException ignored) {}
      try {
        return parseIso8601(s, new ParsePosition(0));
      } catch (ParseException e) {
        throw new JsonSyntaxException(s, e);
      }
    }
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append(SIMPLE_NAME);
    sb.append('(').append(localFormat.getClass().getSimpleName()).append(')');
    return sb.toString();
  }

  public Date readJavaUtilDate(JsonReader in) throws IOException {
    if (in.peek() == JsonToken.NULL) {
      in.nextNull();
      return null;
    }
    synchronized (localFormat) {
      return deserializeToDate(in.nextString());
    }
  }

  public void writeJavaUtilDate(JsonWriter out, Date value) throws IOException {
    if (value == null) {
      out.nullValue();
      return;
    }
    synchronized (localFormat) {
      out.value(formatEnUsDate(value));
    }
  }

  String formatEnUsDate(Date value) {
    synchronized (localFormat) {
      return enUsFormat.format(value);
    }
  }

  Date parseLocalText(String text) throws ParseException {
    synchronized (localFormat) {
      return localFormat.parse(text);
    }
  }

  Date parseEnUsText(String text) throws ParseException {
    synchronized (localFormat) {
      return enUsFormat.parse(text);
    }
  }

  public String formatIso8601(Date date) {
    return formatIso8601(date, false, isoTimeZone);
  }

  public String formatIso8601(Date date, boolean millis) {
    return formatIso8601(date, millis, isoTimeZone);
  }

  public String formatIso8601(Date date, boolean millis, TimeZone tz) {
    Calendar calendar = new GregorianCalendar(tz, isoLocale);
    calendar.setTime(date);

    int capacity = "yyyy-MM-ddThh:mm:ss".length();
    capacity += millis ? ".sss".length() : 0;
    capacity += tz.getRawOffset() == isoTimeZone.getRawOffset() && tz.getRawOffset() == 0
        ? "Z".length() : "+hh:mm".length();
    StringBuilder formatted = new StringBuilder(capacity);

    padIsoInt(formatted, calendar.get(Calendar.YEAR), "yyyy".length());
    formatted.append('-');
    padIsoInt(formatted, calendar.get(Calendar.MONTH) + 1, "MM".length());
    formatted.append('-');
    padIsoInt(formatted, calendar.get(Calendar.DAY_OF_MONTH), "dd".length());
    formatted.append('T');
    padIsoInt(formatted, calendar.get(Calendar.HOUR_OF_DAY), "hh".length());
    formatted.append(':');
    padIsoInt(formatted, calendar.get(Calendar.MINUTE), "mm".length());
    formatted.append(':');
    padIsoInt(formatted, calendar.get(Calendar.SECOND), "ss".length());
    if (millis) {
      formatted.append('.');
      padIsoInt(formatted, calendar.get(Calendar.MILLISECOND), "sss".length());
    }

    int offset = tz.getOffset(calendar.getTimeInMillis());
    if (offset != 0) {
      int hours = Math.abs((offset / (60 * 1000)) / 60);
      int minutes = Math.abs((offset / (60 * 1000)) % 60);
      formatted.append(offset < 0 ? '-' : '+');
      padIsoInt(formatted, hours, "hh".length());
      formatted.append(':');
      padIsoInt(formatted, minutes, "mm".length());
    } else {
      formatted.append('Z');
    }
    return formatted.toString();
  }

  void padIsoInt(StringBuilder buffer, int value, int length) {
    String strValue = Integer.toString(value);
    for (int i = length - strValue.length(); i > 0; i--) {
      buffer.append(isoPadChar);
    }
    buffer.append(strValue);
  }

  public Date parseIso8601(String date, ParsePosition pos) throws ParseException {
    Exception fail = null;
    try {
      int offset = pos.getIndex();

      int year = parseIsoInt(date, offset, offset += 4);
      if (offset < date.length() && date.charAt(offset) == '-') {
        offset += 1;
      }

      int month = parseIsoInt(date, offset, offset += 2);
      if (offset < date.length() && date.charAt(offset) == '-') {
        offset += 1;
      }

      int day = parseIsoInt(date, offset, offset += 2);
      int hour = 0;
      int minutes = 0;
      int seconds = 0;
      int milliseconds = 0;

      boolean hasT = offset < date.length() && date.charAt(offset) == 'T';
      if (!hasT && (date.length() <= offset)) {
        Calendar calendar = new GregorianCalendar(year, month - 1, day);
        pos.setIndex(offset);
        return calendar.getTime();
      }

      if (hasT) {
        hour = parseIsoInt(date, offset += 1, offset += 2);
        if (offset < date.length() && date.charAt(offset) == ':') {
          offset += 1;
        }

        minutes = parseIsoInt(date, offset, offset += 2);
        if (offset < date.length() && date.charAt(offset) == ':') {
          offset += 1;
        }
        if (date.length() > offset) {
          char c = date.charAt(offset);
          if (c != 'Z' && c != '+' && c != '-') {
            seconds = parseIsoInt(date, offset, offset += 2);
            if (seconds > 59 && seconds < 63) {
              seconds = 59;
            }
            if (offset < date.length() && date.charAt(offset) == '.') {
              offset += 1;
              int endOffset = indexOfIsoNonDigit(date, offset + 1);
              int parseEndOffset = Math.min(endOffset, offset + 3);
              int fraction = parseIsoInt(date, offset, parseEndOffset);
              int digitCount = parseEndOffset - offset;
              if (digitCount == 2) {
                milliseconds = fraction * isoRadix;
              } else if (digitCount == 1) {
                milliseconds = fraction * isoRadix * isoRadix;
              } else {
                milliseconds = fraction;
              }
              offset = endOffset;
            }
          }
        }
      }

      TimeZone timezone = resolveIsoTimeZone(date, offset);
      offset = advanceIsoTimeZone(date, offset);

      Calendar calendar = new GregorianCalendar(timezone);
      calendar.setLenient(false);
      calendar.set(Calendar.YEAR, year);
      calendar.set(Calendar.MONTH, month - 1);
      calendar.set(Calendar.DAY_OF_MONTH, day);
      calendar.set(Calendar.HOUR_OF_DAY, hour);
      calendar.set(Calendar.MINUTE, minutes);
      calendar.set(Calendar.SECOND, seconds);
      calendar.set(Calendar.MILLISECOND, milliseconds);

      pos.setIndex(offset);
      return calendar.getTime();
    } catch (IndexOutOfBoundsException e) {
      fail = e;
    } catch (NumberFormatException e) {
      fail = e;
    } catch (IllegalArgumentException e) {
      fail = e;
    }
    String input = (date == null) ? null : ('"' + date + "'");
    String msg = fail.getMessage();
    if (msg == null || msg.isEmpty()) {
      msg = "(" + fail.getClass().getName() + ")";
    }
    ParseException ex = new ParseException("Failed to parse date [" + input + "]: " + msg, pos.getIndex());
    ex.initCause(fail);
    throw ex;
  }

  int parseIsoInt(String value, int beginIndex, int endIndex) {
    if (beginIndex < 0 || endIndex > value.length() || beginIndex > endIndex) {
      throw new NumberFormatException(value);
    }
    int i = beginIndex;
    int result = 0;
    int digit;
    if (i < endIndex) {
      digit = Character.digit(value.charAt(i++), isoRadix);
      if (digit < 0) {
        throw new NumberFormatException("Invalid number: " + value.substring(beginIndex, endIndex));
      }
      result = -digit;
    }
    while (i < endIndex) {
      digit = Character.digit(value.charAt(i++), isoRadix);
      if (digit < 0) {
        throw new NumberFormatException("Invalid number: " + value.substring(beginIndex, endIndex));
      }
      result *= isoRadix;
      result -= digit;
    }
    return -result;
  }

  int indexOfIsoNonDigit(String string, int offset) {
    for (int i = offset; i < string.length(); i++) {
      char c = string.charAt(i);
      if (Character.digit(c, isoRadix) < 0) {
        return i;
      }
    }
    return string.length();
  }

  TimeZone resolveIsoTimeZone(String date, int offset) {
    if (date.length() <= offset) {
      throw new IllegalArgumentException("No time zone indicator");
    }
    char timezoneIndicator = date.charAt(offset);
    if (timezoneIndicator == 'Z') {
      return isoTimeZone;
    }
    if (timezoneIndicator == '+' || timezoneIndicator == '-') {
      String timezoneOffset = date.substring(offset);
      timezoneOffset = timezoneOffset.length() >= 5 ? timezoneOffset : timezoneOffset + "00";
      if ("+0000".equals(timezoneOffset) || "+00:00".equals(timezoneOffset)) {
        return isoTimeZone;
      }
      String timezoneId = "GMT" + timezoneOffset;
      TimeZone timezone = TimeZone.getTimeZone(timezoneId);
      String act = timezone.getID();
      if (!act.equals(timezoneId)) {
        String cleaned = act.replace(":", "");
        if (!cleaned.equals(timezoneId)) {
          throw new IndexOutOfBoundsException("Mismatching time zone indicator: " + timezoneId
              + " given, resolves to " + timezone.getID());
        }
      }
      return timezone;
    }
    throw new IndexOutOfBoundsException("Invalid time zone indicator '" + timezoneIndicator + "'");
  }

  int advanceIsoTimeZone(String date, int offset) {
    if (date.length() <= offset) {
      return offset;
    }
    char timezoneIndicator = date.charAt(offset);
    if (timezoneIndicator == 'Z') {
      return offset + 1;
    }
    if (timezoneIndicator == '+' || timezoneIndicator == '-') {
      String timezoneOffset = date.substring(offset);
      timezoneOffset = timezoneOffset.length() >= 5 ? timezoneOffset : timezoneOffset + "00";
      return offset + timezoneOffset.length();
    }
    return offset;
  }

  public java.sql.Date readSqlDate(JsonReader in) throws IOException {
    synchronized (sqlTemporalLock) {
      if (in.peek() == JsonToken.NULL) {
        in.nextNull();
        return null;
      }
      return parseSqlDateText(in.nextString());
    }
  }

  public void writeSqlDate(JsonWriter out, java.sql.Date value) throws IOException {
    synchronized (sqlTemporalLock) {
      out.value(value == null ? null : formatSqlDate(value));
    }
  }

  String formatSqlDate(java.sql.Date value) {
    synchronized (sqlTemporalLock) {
      return sqlDateFormat.format(value);
    }
  }

  java.sql.Date parseSqlDateText(String text) {
    synchronized (sqlTemporalLock) {
      try {
        return new java.sql.Date(sqlDateMillis(text));
      } catch (ParseException e) {
        throw new JsonSyntaxException(e);
      }
    }
  }

  long sqlDateMillis(String text) throws ParseException {
    synchronized (sqlTemporalLock) {
      return sqlDateFormat.parse(text).getTime();
    }
  }

  public Time readSqlTime(JsonReader in) throws IOException {
    synchronized (sqlTemporalLock) {
      if (in.peek() == JsonToken.NULL) {
        in.nextNull();
        return null;
      }
      return parseSqlTimeText(in.nextString());
    }
  }

  public void writeSqlTime(JsonWriter out, Time value) throws IOException {
    synchronized (sqlTemporalLock) {
      out.value(value == null ? null : formatSqlTime(value));
    }
  }

  String formatSqlTime(Time value) {
    synchronized (sqlTemporalLock) {
      return sqlTimeFormat.format(value);
    }
  }

  Time parseSqlTimeText(String text) {
    synchronized (sqlTemporalLock) {
      try {
        return new Time(sqlTimeMillis(text));
      } catch (ParseException e) {
        throw new JsonSyntaxException(e);
      }
    }
  }

  long sqlTimeMillis(String text) throws ParseException {
    synchronized (sqlTemporalLock) {
      return sqlTimeFormat.parse(text).getTime();
    }
  }

  public Calendar readCalendar(JsonReader in) throws IOException {
    if (in.peek() == JsonToken.NULL) {
      in.nextNull();
      return null;
    }
    in.beginObject();
    int year = 0;
    int month = 0;
    int dayOfMonth = 0;
    int hourOfDay = 0;
    int minute = 0;
    int second = 0;
    while (in.peek() != JsonToken.END_OBJECT) {
      String name = in.nextName();
      int value = in.nextInt();
      if (isCalendarYearField(name)) {
        year = value;
      } else if (isCalendarMonthField(name)) {
        month = value;
      } else if (isCalendarDayField(name)) {
        dayOfMonth = value;
      } else if (isCalendarHourField(name)) {
        hourOfDay = value;
      } else if (isCalendarMinuteField(name)) {
        minute = value;
      } else if (isCalendarSecondField(name)) {
        second = value;
      }
    }
    in.endObject();
    return createCalendar(year, month, dayOfMonth, hourOfDay, minute, second);
  }

  public void writeCalendar(JsonWriter out, Calendar value) throws IOException {
    if (value == null) {
      out.nullValue();
      return;
    }
    out.beginObject();
    writeCalendarField(out, calendarKeys[0], readCalendarField(value, calendarKeys[0]));
    writeCalendarField(out, calendarKeys[1], readCalendarField(value, calendarKeys[1]));
    writeCalendarField(out, calendarKeys[2], readCalendarField(value, calendarKeys[2]));
    writeCalendarField(out, calendarKeys[3], readCalendarField(value, calendarKeys[3]));
    writeCalendarField(out, calendarKeys[4], readCalendarField(value, calendarKeys[4]));
    writeCalendarField(out, calendarKeys[5], readCalendarField(value, calendarKeys[5]));
    out.endObject();
  }

  void writeCalendarField(JsonWriter out, String name, int value) throws IOException {
    if (isCalendarYearField(name) || isCalendarMonthField(name) || isCalendarDayField(name)
        || isCalendarHourField(name) || isCalendarMinuteField(name) || isCalendarSecondField(name)) {
      out.name(name);
      out.value(value);
      return;
    }
    throw new JsonSyntaxException("Unknown calendar field: " + name);
  }

  Calendar createCalendar(int year, int month, int dayOfMonth, int hourOfDay, int minute, int second) {
    return new GregorianCalendar(year, month, dayOfMonth, hourOfDay, minute, second);
  }

  int readCalendarField(Calendar value, String name) {
    if (isCalendarYearField(name)) {
      return value.get(Calendar.YEAR);
    }
    if (isCalendarMonthField(name)) {
      return value.get(Calendar.MONTH);
    }
    if (isCalendarDayField(name)) {
      return value.get(Calendar.DAY_OF_MONTH);
    }
    if (isCalendarHourField(name)) {
      return value.get(Calendar.HOUR_OF_DAY);
    }
    if (isCalendarMinuteField(name)) {
      return value.get(Calendar.MINUTE);
    }
    if (isCalendarSecondField(name)) {
      return value.get(Calendar.SECOND);
    }
    throw new JsonSyntaxException("Unknown calendar field: " + name);
  }

  boolean isCalendarYearField(String name) {
    return calendarKeys[0].equals(name);
  }

  boolean isCalendarMonthField(String name) {
    return calendarKeys[1].equals(name);
  }

  boolean isCalendarDayField(String name) {
    return calendarKeys[2].equals(name);
  }

  boolean isCalendarHourField(String name) {
    return calendarKeys[3].equals(name);
  }

  boolean isCalendarMinuteField(String name) {
    return calendarKeys[4].equals(name);
  }

  boolean isCalendarSecondField(String name) {
    return calendarKeys[5].equals(name);
  }

  public Locale readLocale(JsonReader in) throws IOException {
    if (in.peek() == JsonToken.NULL) {
      in.nextNull();
      return null;
    }
    return buildLocale(tokenizeLocale(in.nextString()));
  }

  public void writeLocale(JsonWriter out, Locale value) throws IOException {
    out.value(value == null ? null : joinLocale(value));
  }

  StringTokenizer tokenizeLocale(String locale) {
    return new StringTokenizer(locale, localeSeparator);
  }

  Locale buildLocale(StringTokenizer tokenizer) {
    String language = nextLocalePart(tokenizer);
    String country = nextLocalePart(tokenizer);
    String variant = nextLocalePart(tokenizer);
    return composeLocale(language, country, variant);
  }

  String nextLocalePart(StringTokenizer tokenizer) {
    if (tokenizer.hasMoreElements()) {
      return tokenizer.nextToken();
    }
    return null;
  }

  Locale composeLocale(String language, String country, String variant) {
    if (country == null && variant == null) {
      return new Locale(language);
    }
    if (variant == null) {
      return new Locale(language, country);
    }
    return new Locale(language, country, variant);
  }

  String joinLocale(Locale value) {
    return value.toString().replace("_", localeSeparator);
  }

  public JsonElement readJsonElement(JsonReader in) throws IOException {
    JsonToken peeked = in.peek();
    if (peeked == nullToken) {
      in.nextNull();
      return JsonNull.INSTANCE;
    }
    switch (peeked) {
    case STRING:
      return new JsonPrimitive(in.nextString());
    case NUMBER:
      return new JsonPrimitive(new LazilyParsedNumber(in.nextString()));
    case BOOLEAN:
      return new JsonPrimitive(in.nextBoolean());
    case BEGIN_ARRAY:
      return readJsonArray(in);
    case BEGIN_OBJECT:
      return readJsonObject(in);
    case END_DOCUMENT:
    case NAME:
    case END_OBJECT:
    case END_ARRAY:
    default:
      throw new IllegalArgumentException();
    }
  }

  JsonArray readJsonArray(JsonReader in) throws IOException {
    JsonArray array = new JsonArray();
    in.beginArray();
    while (in.hasNext()) {
      if (in.peek() == nullToken) {
        in.nextNull();
        array.add(JsonNull.INSTANCE);
      } else {
        array.add(readJsonElement(in));
      }
    }
    in.endArray();
    return array;
  }

  JsonObject readJsonObject(JsonReader in) throws IOException {
    JsonObject object = new JsonObject();
    in.beginObject();
    while (in.hasNext()) {
      String name = in.nextName();
      if (in.peek() == nullToken) {
        in.nextNull();
        object.add(name, JsonNull.INSTANCE);
      } else {
        object.add(name, readJsonElement(in));
      }
    }
    in.endObject();
    return object;
  }

  public void writeJsonElement(JsonWriter out, JsonElement value) throws IOException {
    if (value == null || value.isJsonNull()) {
      if (nullToken == JsonToken.NULL) {
        out.nullValue();
        return;
      }
    }
    if (value.isJsonPrimitive()) {
      writeJsonPrimitive(out, value.getAsJsonPrimitive());
      return;
    }
    if (value.isJsonArray()) {
      out.beginArray();
      for (JsonElement e : value.getAsJsonArray()) {
        writeJsonElement(out, e);
      }
      out.endArray();
      return;
    }
    if (value.isJsonObject()) {
      out.beginObject();
      for (Map.Entry<String, JsonElement> e : value.getAsJsonObject().entrySet()) {
        out.name(e.getKey());
        writeJsonElement(out, e.getValue());
      }
      out.endObject();
      return;
    }
    throw new IllegalArgumentException("Couldn't write " + value.getClass());
  }

  void writeJsonPrimitive(JsonWriter out, JsonPrimitive primitive) throws IOException {
    if (primitive == null && nullToken == JsonToken.NULL) {
      out.nullValue();
      return;
    }
    if (primitive.isNumber()) {
      out.value(primitive.getAsNumber());
    } else if (primitive.isBoolean()) {
      out.value(primitive.getAsBoolean());
    } else {
      out.value(primitive.getAsString());
    }
  }

  public BitSet readBitSet(JsonReader in) throws IOException {
    BitSet bitset = new BitSet();
    in.beginArray();
    int i = 0;
    JsonToken tokenType = in.peek();
    while (tokenType != JsonToken.END_ARRAY) {
      boolean set = parseBitSetToken(in, tokenType);
      if (set) {
        bitset.set(i);
      }
      ++i;
      tokenType = in.peek();
    }
    in.endArray();
    return bitset;
  }

  boolean parseBitSetToken(JsonReader in, JsonToken tokenType) throws IOException {
    if (tokenType == nullToken) {
      in.nextNull();
      return false;
    }
    switch (tokenType) {
    case NUMBER:
      return in.nextInt() != 0;
    case BOOLEAN:
